{
  "name": "opencode-aiway-auth",
  "version": "1.0.22",
  "description": "OpenCode plugin for AI Way authentication and model discovery",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "tsc",
    "integration": "npx tsx test/integration.ts",
    "test:jsonc": "npx tsx test/jsonc-config.ts",
    "test:flat": "npx tsx test/flat-options.ts",
    "test:pricing": "npx tsx test/pricing-map.ts"
  },
  "keywords": [
    "opencode",
    "plugin",
    "aiway",
    "ai-way",
    "llm",
    "auth"
  ],
  "author": "best-linux-code",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/best-linux-code/opencode-aiway-auth.git"
  },
  "bugs": {
    "url": "https://github.com/best-linux-code/opencode-aiway-auth/issues"
  },
  "homepage": "https://github.com/best-linux-code/opencode-aiway-auth#readme",
  "dependencies": {
    "@opencode-ai/plugin": "^0.15.30",
    "jsonc-parser": "^3.3.1"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "tsx": "^4.19.0",
    "typescript": "^5.7.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.4.0"
  }
}
